class ApiError extends Error{constructor(readonly status:number,message:string){super(message);this.name="ApiError"}}
const api=async(path:string,init?:RequestInit)=>{const response=await fetch(`${API}${path}`,init);if(!response.ok&&(!init?.method||init.method.toUpperCase()==="GET")){const body=await response.clone().json().catch(()=>undefined);const error=providerErrorPresentation(body,response.status);throw new ApiError(response.status,`${error.code}: ${error.title}. ${error.message}`)}return response};
const optionalJson=async(path:string,init?:RequestInit)=>{const response=await fetch(`${API}${path}`,init);if(response.status===404||response.status===405||response.status===501)return undefined;if(!response.ok){const body=await response.json().catch(()=>undefined);const error=providerErrorPresentation(body,response.status);throw new ApiError(response.status,`${error.code}: ${error.title}. ${error.message}`)}return response.json()};
const simpleStatus=(value:string,creating=false)=>{if(creating)return "Planning...";const state=value.toLowerCase();if(state.includes("interrupted")||state.includes("restored")||state.includes("failed")||state.includes("unable"))return value;if(state.includes("check")||state.includes("verify"))return "Verifying...";if(state.includes("schematic"))return "Generating schematic...";if(state.includes("geometry")||state.includes("assembly")||state.includes("3d"))return "Building 3D...";if(state.includes("ready"))return "Ready";return value};
